import net.minecraft.network.chat.Component;
import net.minecraft.world.item.*;

/** Proposed source processing over finite actual Depot/Belt owners; runtime UNRUN. */
public final class LegacyMaterialTransportGameTests {
 private static ItemStack light(){var stack=new ItemStack(Items.GLOWSTONE,4);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Canonical finite native light stock"));return stack;}
 @GameTest public void realFabricAbortRestoresLastNativeCompoundWithoutLosingHiddenComponents(GameTestHelper h){var source=source(h,1,4);var original=source.getItem();original.set(DataComponents.CUSTOM_NAME,Component.literal("Last actual charged native source"));try(var transaction=Transaction.openOuter()){var actual=new LegacyCompoundSource(source,original);var paid=actual.takeOne(transaction);h.assertTrue(original.isEmpty()&&original.getComponentsPatch().isEmpty()&&paid.getCount()==1&&paid.has(DataComponents.CUSTOM_NAME),"Genuine native empty stack hides components after actual last-item split");}h.assertTrue(source.getItem()==original&&original.getCount()==1&&original.has(DataComponents.CUSTOM_NAME)&&AllItems.CHROMATIC_COMPOUND.getLight(original)==4&&LegacyMaterialTestFixtures.capture(h.getLevel()).getListOrEmpty("Pending").isEmpty(),"Real Fabric abort restores only exact original native count/metadata; no paid result was published");h.succeed();}
 @GameTest public void depotChargesActualCompoundAndConsumesCanonicalSlotWithMetadataIntact(GameTestHelper h){h.setBlock(LIGHT,AllBlocks.DEPOT);var depot=h.getBlockEntity(LIGHT,DepotBlockEntity.class);try(var transaction=Transaction.openOuter()){h.assertTrue(depot.inventory.automation.insert(ItemVariant.of(light()),4,transaction)==4,"Actual finite Depot slot seeded");transaction.commit();}var metadata=depot.getTransportedItem();metadata.processedBy=FanProcessing.Type.SPLASHING;metadata.processingTime=43;metadata.lastProcessingTick=91;metadata.angle=73;depot.setTransportedItem(metadata);var view=depot.getHeldItem();view.setCount(64);var source=source(h,2,0);source.getItem().set(DataComponents.CUSTOM_NAME,Component.literal("Actual compound metadata follows charged split"));h.assertTrue(LegacyTransportLights.process(AllItems.CHROMATIC_COMPOUND,source,source.getItem(),h.absolutePos(LIGHT)),"Actual Depot optical transport route");var left=depot.getHeldItem();var current=depot.getTransportedItem();var output=nearby(h,AllItems.CHROMATIC_COMPOUND).stream().filter(entity->AllItems.CHROMATIC_COMPOUND.getLight(entity.getItem())==1).findFirst().orElseThrow();h.assertTrue(left.getCount()==3&&left.has(DataComponents.CUSTOM_NAME)&&source.getItem().getCount()==1&&output.getItem().getCount()==1&&output.getItem().has(DataComponents.CUSTOM_NAME),"Only canonical four-item slot pays one; mutating a copied held-stack view cannot mint stock or enlarge paid source");h.assertTrue(current.id.equals(metadata.id)&&current.processingTime==43&&current.lastProcessingTick==91&&current.processedBy==FanProcessing.Type.SPLASHING&&current.angle==73,"Source light use preserves remaining Depot transport/fan metadata");h.succeed();}
 @GameTest public void beltRefusalKeepsPaidChargedOutputAndExactRemainingTransportState(GameTestHelper h){var start=new BlockPos(1,3,3);var end=start.east(5);h.setBlock(start,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));h.setBlock(end,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));h.assertTrue(BeltConnectorItem.createBelts(h.getLevel(),h.absolutePos(start),h.absolutePos(end)),"Actual native finite Belt chain");var controller=h.getBlockEntity(start,BeltBlockEntity.class);var segment=h.getBlockEntity(LIGHT,BeltBlockEntity.class);try(var transaction=Transaction.openOuter()){h.assertTrue(controller.getInventory().segment(segment.index,Direction.UP).insert(ItemVariant.of(light()),4,transaction)==4,"Actual belt stock seeded");transaction.commit();}var actual=controller.getInventory().getTransportedItems().getFirst();actual.processedBy=FanProcessing.Type.SPLASHING;actual.processingTime=29;actual.lastProcessingTick=83;actual.pendingFanResults=List.of(new ItemStack(Items.DIAMOND));actual.heldBy=h.absolutePos(LIGHT.above());actual.locked=true;actual.angle=81;var source=source(h,2,0);var observation=new LegacyMaterialTestFixtures.Observation();LegacyMaterialTestFixtures.with(h.getLevel(),source,null,LegacyMaterialTestFixtures.Mode.REFUSE,observation,()->h.assertTrue(LegacyTransportLights.process(AllItems.CHROMATIC_COMPOUND,source,source.getItem(),h.absolutePos(LIGHT)),"Actual source Belt optical route"));h.assertTrue(controller.getInventory().byId(actual.id)==actual&&actual.stack.getCount()==3&&actual.stack.has(DataComponents.CUSTOM_NAME)&&actual.processingTime==29&&actual.lastProcessingTick==83&&actual.pendingFanResults.size()==1&&actual.heldBy.equals(h.absolutePos(LIGHT.above()))&&actual.locked&&actual.angle==81,"Exact live Belt slot pays one while all source transport/fan state survives");h.assertTrue(source.getItem().getCount()==1&&LegacyMaterialTestFixtures.owned(h.getLevel(),AllItems.CHROMATIC_COMPOUND)==1,"Native output refusal does not refund canonical Belt light or compound payment");var endpoint=observation.endpoint;LegacyMaterialTestFixtures.retry(h.getLevel());h.assertTrue(h.getLevel().getEntity(endpoint.getUUID())==endpoint&&AllItems.CHROMATIC_COMPOUND.getLight(endpoint.getItem())==1,"Single original charged endpoint retries after finite canonical Belt payment");h.succeed();}
 @GameTest public void nonLuminousDepotCargoDoesNotDebitCompoundOrTransport(GameTestHelper h){h.setBlock(LIGHT,AllBlocks.DEPOT);var depot=h.getBlockEntity(LIGHT,DepotBlockEntity.class);try(var transaction=Transaction.openOuter()){depot.inventory.automation.insert(ItemVariant.of(Items.STONE),4,transaction);transaction.commit();}var source=source(h,2,0);h.assertTrue(!LegacyTransportLights.process(AllItems.CHROMATIC_COMPOUND,source,source.getItem(),h.absolutePos(LIGHT))&&source.getItem().getCount()==2&&depot.getHeldItem().getCount()==4&&LegacyMaterialTestFixtures.capture(h.getLevel()).getListOrEmpty("Pending").isEmpty(),"Genuine nonluminous block state never creates payment or a prospective result claim");h.succeed();}
}
